const HOST='feature-domain-stages5-10-integration-20261030-ngeblogging.triapriyogibahari7.workers.dev';
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
function domain(value){if(typeof value!=='string')throw Error();const raw=value.trim().replace(/\.$/,'');if(!raw||/[\s/\\:@?#%]/u.test(raw))throw Error();const name=new URL('https://'+raw).hostname.toLowerCase();if(name.length>253||!name.includes('.')||/^\d+(?:\.\d+){3}$/.test(name)||name.split('.').some(x=>!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(x)))throw Error();return name;}
const price=q=>q?.displayCurrency==='USD'&&q.currency==='IDR'&&q.years===1&&typeof q.salePriceUsd==='string'&&/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(q.salePriceUsd)&&Number(q.salePriceUsd)>0&&Number.isSafeInteger(q.amountIdr)&&q.amountIdr>0&&q.amountIdr<=1000000000000;
export function createSandboxController({getSession,fetchImpl=globalThis.fetch,store,makeKey=()=>crypto.randomUUID(),getOrigin=()=>location.origin,onChange=()=>{}}){
 let owner=null,knownToken=null,q=null,key=null,record=null,order=null,busy=false,controller=null,phase='idle',message='Uji admin sandbox saja. Tidak ada pembayaran atau pembelian domain.';
 const session=()=>{try{const s=getSession();return typeof s?.userId==='string'&&UUID.test(s.userId)&&typeof s.accessToken==='string'&&/^[^\s]{1,8192}$/.test(s.accessToken)?{userId:s.userId.toLowerCase(),accessToken:s.accessToken}:null;}catch{return null;}};
 const view=()=>({phase,message,busy,hasPendingRecord:!!record,canQuote:!!owner&&!busy&&!record,canOrder:!!owner&&!busy&&!!(q||record),quote:q?{...q}:null,orderId:order?.orderId||null});
 const emit=()=>{try{onChange(view());}catch{}};
 function sync(){const s=session(),id=s?.userId||null,token=s?.accessToken||null;if(id!==owner){owner=id;q=null;key=null;record=null;order=null;phase=owner?'idle':'auth_required';message=owner?'Uji admin sandbox saja. Tidak ada pembayaran atau pembelian domain.':'Login dengan akun yang sudah ada; tidak perlu mendaftar ulang.';if(owner){try{const r=store.load(owner);if(r?.userId===owner&&typeof r.quoteId==='string'&&typeof r.idempotencyKey==='string'&&UUID.test(r.quoteId)&&UUID.test(r.idempotencyKey)&&Object.keys(r).length===3){record={userId:owner,quoteId:r.quoteId.toLowerCase(),idempotencyKey:r.idempotencyKey.toLowerCase()};phase='resume';message='Ada permintaan sandbox tersimpan. Ulangi dengan kunci yang sama; pesanan dapat dibuat jika sebelumnya belum dibuat. Tidak ada pembayaran.';}}catch{}}}else if(token!==knownToken){q=null;order=null;phase=record?'resume':'idle';message='Sesi diperbarui. Minta quote baru atau periksa permintaan tersimpan dengan kunci yang sama.';}if(!owner){phase='auth_required';message='Login dengan akun yang sudah ada; tidak perlu mendaftar ulang.';}knownToken=token;return s;}
 const same=s=>{const current=session();return current?.userId===s.userId&&current.accessToken===s.accessToken;};
 function gate(){let origin;try{origin=new URL(getOrigin());}catch{}if(origin?.protocol!=='https:'||origin.hostname!==HOST||origin.port||origin.username||origin.password){message='Gunakan hostname preview resmi tahap 6.';phase='blocked';emit();return null;}const s=sync();if(!s)emit();return s;}
 async function send(path,s,body){controller=new AbortController();let rejectAbort;const stopped=new Promise((_,reject)=>{rejectAbort=()=>reject(Error('STOPPED'));controller.signal.addEventListener('abort',rejectAbort,{once:true});});const timer=setTimeout(()=>controller.abort(),25000);try{const response=await Promise.race([fetchImpl(path,{method:'POST',redirect:'error',cache:'no-store',credentials:'omit',headers:{Authorization:'Bearer '+s.accessToken,...(body?{'content-type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:controller.signal}),stopped]);const data=await Promise.race([response.json(),stopped]);return {status:response.status,data};}finally{clearTimeout(timer);controller.signal.removeEventListener('abort',rejectAbort);controller=null;}}
 function changed(){sync();q=null;order=null;message='Sesi berubah. Hasil dari sesi sebelumnya tidak ditampilkan.';phase='auth_changed';}
 async function quote(raw){if(busy)return false;const s=gate();if(!s)return false;if(record){message='Selesaikan pemeriksaan permintaan sandbox tersimpan; jangan membuat kunci baru.';emit();return false;}let name;try{name=domain(raw);}catch{phase='invalid_domain';message='Masukkan domain lengkap tanpa https:// atau path.';emit();return false;}busy=true;q=null;key=null;phase='loading_quote';message='Meminta quote sandbox dari backend...';emit();try{const {status,data:d}=await send('/api/commerce/domains/quote/'+encodeURIComponent(name),s);if(!same(s)){changed();return false;}if(status!==201||d?.code!=='DOMAIN_QUOTE_PREVIEW'||d.lookupOnly!==true||d.purchaseAllowed!==false||d.checkoutCreated!==false||d.registrationStarted!==false){phase='quote_unavailable';message=d?.code==='DOMAIN_QUOTE_PREVIEW_DISABLED'?'Backend quote masih nonaktif. Tidak ada quote yang dikonfirmasi.':d?.code==='DOMAIN_PRICING_INPUTS_UNAVAILABLE'?'Snapshot biaya/kurs backend belum siap. Tidak menggunakan harga contoh.':'Quote belum terkonfirmasi. Tidak ada pembayaran atau pembelian domain.';return false;}const x=d.quote;if(typeof x?.quoteId!=='string'||!UUID.test(x.quoteId)||x.domain!==name||!price(x)||x.indicative!==true||typeof x.expiresAt!=='string'||!Number.isFinite(Date.parse(x.expiresAt)))throw Error();const next=makeKey();if(typeof next!=='string'||!UUID.test(next))throw Error();q=Object.freeze({quoteId:x.quoteId.toLowerCase(),domain:name,years:1,displayCurrency:'USD',salePriceUsd:x.salePriceUsd,currency:'IDR',amountIdr:x.amountIdr,expiresAt:x.expiresAt});key=next.toLowerCase();phase='quote_ready';message='Quote sandbox diterima. Bukan checkout dan belum ada pembayaran.';return true;}catch{if(!same(s))changed();else{phase='quote_unavailable';message='Quote belum terkonfirmasi. Coba lagi tanpa memakai harga contoh.';}return false;}finally{busy=false;emit();}}
 async function orderAttempt(){if(busy)return false;const s=gate();if(!s||(!q&&!record))return false;if(!record){const next={userId:s.userId,quoteId:q.quoteId,idempotencyKey:key};try{if(store.save({...next})!==true)throw Error();record=next;}catch{phase='storage_required';message='Kunci pengulangan tidak dapat disimpan. Permintaan pesanan dibatalkan sebelum dikirim.';emit();return false;}}busy=true;phase='loading_order';message='Mengirim ulang kunci yang sama untuk pesanan sandbox. Tidak membuat pembayaran.';emit();try{const {status,data:d}=await send('/api/commerce/domains/order',s,{quoteId:record.quoteId,idempotencyKey:record.idempotencyKey});if(!same(s)){changed();return false;}if(d?.code==='QUOTE_EXPIRED'&&status===409){try{if(store.remove(owner)!==true)throw Error();record=null;q=null;key=null;phase='quote_expired';message='Backend menolak quote kedaluwarsa. Minta quote baru.';}catch{phase='order_unknown';message='Quote kedaluwarsa; kunci uji masih tersimpan. Tidak membuat kunci baru.';}return false;}if(d?.code==='ORDER_ALREADY_PROCESSED'&&status===409){phase='processed';message='Backend menyatakan pesanan sudah diproses. Ini bukan konfirmasi pembayaran; jangan buat ulang.';return false;}const o=d?.order;if(![200,201].includes(status)||d?.code!=='DOMAIN_ORDER_PREVIEW'||d.purchaseAllowed!==false||d.checkoutCreated!==false||d.registrationStarted!==false||typeof o?.orderId!=='string'||!/^DOM-[a-f0-9]{40}$/.test(o.orderId)||o.quoteId!==record.quoteId||o.reused!==(status===200)||!price(o)||o.paymentState!=='pending'||o.registrationState!=='not_started'||domain(o.domain)!==o.domain||(q&&(o.domain!==q.domain||o.amountIdr!==q.amountIdr||o.salePriceUsd!==q.salePriceUsd)))throw Error();order={orderId:o.orderId};phase='order_confirmed';message='Pesanan sandbox tersimpan, status pending. Belum dibayar dan belum didaftarkan ke registrar.';return true;}catch{if(!same(s))changed();else{phase='order_unknown';message='Hasil pesanan belum terkonfirmasi. Gunakan tombol ulang dengan kunci yang sama; jangan membuat kunci baru.';}return false;}finally{busy=false;emit();}}
 function refresh(){const s=session();if((s?.userId||null)!==owner||(s?.accessToken||null)!==knownToken){controller?.abort();sync();}emit();}
 function invalidateQuote(){if(busy||record)return;q=null;key=null;phase='idle';message='Domain berubah. Minta quote baru.';emit();}
 sync();emit();return {quote,orderAttempt,refresh,invalidateQuote,view};
}
function mount(){
 const output=document.getElementById('result');if(!output||location.protocol!=='https:'||location.hostname!==HOST)return;
 const box=document.createElement('section'),title=document.createElement('h2'),note=document.createElement('p'),label=document.createElement('label'),input=document.createElement('input'),quote=document.createElement('button'),order=document.createElement('button'),result=document.createElement('pre');
 title.textContent='Uji quote dan pesanan sandbox';note.textContent='Khusus admin preview. Menyimpan quote/pesanan hanya bila backend diaktifkan dan biaya siap. Tidak membuat pembayaran, membeli domain, atau mengubah DNS.';label.textContent='Domain untuk quote sandbox: ';input.type='text';input.maxLength=253;input.placeholder='nama-domain.com';input.autocomplete='off';input.spellcheck=false;label.append(input);quote.type=order.type='button';quote.textContent='Minta quote sandbox';order.textContent='Buat / periksa pesanan sandbox';result.setAttribute('aria-live','polite');box.append(title,note,label,quote,order,result);output.before(box);
 const prefix='ngeblogging-stage6-sandbox-attempt:';
 const store={load:id=>JSON.parse(sessionStorage.getItem(prefix+id)||'null'),save:r=>{sessionStorage.setItem(prefix+r.userId,JSON.stringify(r));return true;},remove:id=>{sessionStorage.removeItem(prefix+id);return true;}};
 const getSession=()=>{try{const raw=localStorage.getItem('sb-polvmlrhqoiflumibfqs-auth-token');if(!raw||raw.length>100000)return null;const s=JSON.parse(raw);if(!Number.isFinite(s?.expires_at)||s.expires_at*1000<=Date.now())return null;return {userId:s.user?.id,accessToken:s.access_token};}catch{return null;}};
 const c=createSandboxController({getSession,store,onChange:v=>{quote.disabled=!v.canQuote;order.disabled=!v.canOrder;input.disabled=v.busy||v.hasPendingRecord;result.textContent=v.message+(v.quote?'\nDomain: '+v.quote.domain+'\nRetail: USD '+v.quote.salePriceUsd+'\nNominal: IDR '+v.quote.amountIdr.toLocaleString('id-ID')+'\nBerlaku sampai: '+v.quote.expiresAt:'')+(v.orderId?'\nID pesanan sandbox: '+v.orderId:'');}});
 input.addEventListener('input',()=>c.invalidateQuote());quote.addEventListener('click',()=>c.quote(input.value));order.addEventListener('click',()=>{const v=c.view();try{if(v.quote&&domain(input.value)!==v.quote.domain){c.invalidateQuote();return;}}catch{c.invalidateQuote();return;}if(window.confirm('Lanjutkan pemeriksaan/pembuatan pesanan sandbox memakai kunci yang sama? Tidak ada pembayaran atau pembelian domain.'))c.orderAttempt();});
 window.addEventListener('storage',event=>{if(event.key===null||event.key==='sb-polvmlrhqoiflumibfqs-auth-token')c.refresh();});window.addEventListener('focus',()=>c.refresh());
}
if(typeof document!=='undefined'){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();}
